head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf90004";
scwin.dmenus = undefined;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — bndMktactTpCd, packDeclIsurPriorredmpt, isur_cd, ipt_bndMktactTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf90004.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_4_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '205'); } }, { id: "c_when_5_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '305'); } }, { id: "c_when_6_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '303'); } }, { id: "c_when_7_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '304'); } }, { id: "c_when_8_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '302'); } }, { id: "c_when_9_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '315'); } }, { id: "c_when_10_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '330'); } }, { id: "c_when_11_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '309'); } }, { id: "c_when_12_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '308'); } }, { id: "c_when_13_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '307'); } }, { id: "c_when_14_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '306'); } }, { id: "c_when_15_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '311'); } }, { id: "c_when_16_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '316'); } }, { id: "c_when_17_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '301'); } }, { id: "if_packDeclIsurPriorredmpt", fn: function(){ return (((dma_pageContext.get("packDeclIsurPriorredmpt") ?? "") === 'Y')); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_bndMktactTpCd", fn: function () { return String(String((dma_pageContext.get("bndMktactTpCd") ?? ""))); } },
        { childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("isurNm") ?? ""))); } },
        { childId: "__rb1", fn: function () { return String(String((dma_pageContext.get("isurCd") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

