// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 2개다(tx_fn_searchList, tx_fn_openRequest) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_searchList_onclick
 * @description btn_searchList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchList_onclick = async function(e){
    try {
        await scwin.searchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf90004.btn_searchList_onclick' }); }
};

/**
 * @method
 * @name ipt_searchWord_onkeypress
 * @description ipt_searchWord onkeypress 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_searchWord_onkeypress = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        $c.str.replaceAll(selfVar);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf90004.ipt_searchWord_onkeypress' }); }
};

/**
 * @method
