 */
scwin.ipt_searchWord_onpaste = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf90004.ipt_searchWord_onpaste' }); }
};

/**
 * @method
