/**
 * @method
 * @name openRequest
 * @description open Request 처리
 * @param {*} _std_cd _std_cd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openRequest = async function (_std_cd) {
    const frm = (document.SearchForm || { elements: [] });
    const _bnd_mktact_tp_cd = $c.util.getComponent("dma_searchListReq").get("bndMktactTpCd");
    $c.util.getComponent("dma_searchListReq").set("stdCd", _std_cd);
    frm.action = '/event/event.do';
    $c.util.getComponent("dma_searchListReq").set("method", 'floatingRateView');
    frm.target = '_self';
    await scwin.tx_fn_openRequest();
};

